use sarv_quote::{store::Store,domain::State};
use std::{path::Path,fs};
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<_>=std::env::args().collect();let dir=Path::new(&args[1]);let envelope:serde_json::Value=serde_json::from_slice(&fs::read(&args[2])?)?;let prior:State=serde_json::from_value(envelope["state"].clone())?;assert_eq!(prior.schema,2);let s=Store::open(dir)?;assert_eq!(s.state.schema,3);assert_eq!(s.local_generation(),18);let mut expected=serde_json::to_value(&prior)?;expected["schema"]=3.into();assert_eq!(expected,serde_json::to_value(&s.state)?);let files=fs::read_dir(dir)?.map(|x|x.unwrap().path()).filter(|p|p.file_name().unwrap().to_str().unwrap().starts_with("before-schema3-")).collect::<Vec<_>>();assert_eq!(files.len(),1);let recovery:serde_json::Value=serde_json::from_slice(&fs::read(&files[0])?)?;assert_eq!(recovery["format"],"sarv-accounting-backup-v2");assert_eq!(recovery["state"],envelope["state"]);assert_eq!(serde_json::to_value(Store::restore_preview(&files[0])?)?,expected);let restored=Store::restore_preview(&files[0])?;let mut fresh=Store::open(&dir.join("fresh-restore"))?;fresh.restore(restored)?;assert_eq!(serde_json::to_value(&fresh.state)?,expected);drop(s);let s=Store::open(dir)?;assert_eq!(s.local_generation(),18);assert_eq!(serde_json::to_value(&s.state)?,expected);println!("PASS independent Store.open schema2→3: generation17→18, exact3quote/3journal/date/ID/history preservation, one verified v2 recovery retaining original state, idempotent repeat-open18, fresh restore exact");Ok(())}
